// Sort P2_RULES by descending pattern length
P2_RULES.sort((a, b) => b[0].source.length - a[0].source.length);

/**
 * Convert Sinhala Unicode text to Legacy FM Font (FM-Abhaya, FM-Derana, etc.)
 */
function unicodeToFM(inputText) {
  if (!inputText) return '';
  let text = inputText;

  // Phase 1: Escape conflict punctuation
  for (const [reg, rep] of P1_MAP) {
    text = text.replace(reg, rep);
  }

  // Phase 2: Sinhala characters
  for (const [reg, rep] of P2_RULES) {
    text = text.replace(reg, rep);
  }

  // Phase 3: Punctuation resolution
  for (const [reg, rep] of P3_MAP) {
    text = text.replace(reg, rep);
  }

  return text;
}

