const FM_PUNC_TO_UNI = [
  [/\"/g, ","],
  [/\$/g, "/"],
  [/&/g, ")"],
  [/\^/g, "("],
  [/@/g, "?"],
  [/`/g, "!"],
  [/\}/g, "="],
  [/~/g, "'"],
  [/¤/g, "+"],
  [/•/g, ":"],
  [/∙/g, ";"],
  [/\]/g, "%"],
  [/'/g, "."]
];

FM_TO_UNI.sort((a, b) => b[0].source.length - a[0].source.length);

/**
 * Convert FM Legacy Font text back to Unicode Sinhala
 */
function fmToUnicode(inputText) {
  if (!inputText) return '';
  let text = inputText;
  for (const [reg, rep] of FM_TO_UNI) {
    text = text.replace(reg, rep);
  }
  for (const [reg, rep] of FM_PUNC_TO_UNI) {
    text = text.replace(reg, rep);
  }
  return text;
}

