/**
 * Phonetically transliterate raw English syllable characters to Sinhala
 */
function rawPhoneticConvert(str) {
  let text = str;

  // Repaya (R followed by consonant)
  text = text.replace(/R([kKgGjJtTdDnpbBmyrlvwsShf])/g, 'ර්‍$1');

  // ru and ruu signs (e.g. kru -> කෘ, kruu -> කෲ)
  for (const c of SINGLISH_CONSONANTS) {
    text = text.replace(new RegExp(c.k + 'ruu', 'g'), c.u + 'ෲ');
    text = text.replace(new RegExp(c.k + 'ru', 'g'), c.u + 'ෘ');
  }

  // Yanshaya (c + y + vowel)
  for (const c of SINGLISH_CONSONANTS) {
    if (c.k === 'y' || c.k === 'r') continue;
    for (const v of SINGLISH_VOWELS) {
      text = text.replace(new RegExp(c.k + 'y' + v.k, 'g'), c.u + '්‍ය' + v.m);
    }
    text = text.replace(new RegExp(c.k + 'y', 'g'), c.u + '්‍ය');
  }

  // Rakaranshaya (c + r + vowel)
  for (const c of SINGLISH_CONSONANTS) {
    if (c.k === 'r') continue;
    for (const v of SINGLISH_VOWELS) {
      text = text.replace(new RegExp(c.k + 'r' + v.k, 'g'), c.u + '්‍ර' + v.m);
    }
    text = text.replace(new RegExp(c.k + 'r', 'g'), c.u + '්‍ර');
  }

  // Consonant + Vowel modifiers
  for (const c of SINGLISH_CONSONANTS) {
    for (const v of SINGLISH_VOWELS) {
      text = text.replace(new RegExp(c.k + v.k, 'g'), c.u + v.m);
    }
  }

  // Consonant + Virama (Hal kirima)
  for (const c of SINGLISH_CONSONANTS) {
    text = text.replace(new RegExp(c.k, 'g'), c.u + '්');
  }

  // Independent Vowels
  for (const v of SINGLISH_VOWELS) {
    text = text.replace(new RegExp(v.k, 'g'), v.u);
  }

  return text;
}

/**
 * Convert a single Singlish token or word to Sinhala Unicode
 */
function convertSinglishWord(word) {
  if (!word) return '';
  const lower = word.toLowerCase();
  if (SINGLISH_DICTIONARY[lower]) return SINGLISH_DICTIONARY[lower];

  // Verb suffix: -nawa / -navaa -> ...නවා (e.g. samaranawa -> සමරනවා)
  if (/(.+)nawa$/i.test(word)) {
    const m = word.match(/^(.+)nawa$/i);
    return rawPhoneticConvert(m[1]) + 'නවා';
  }
  if (/(.+)navaa$/i.test(word)) {
    const m = word.match(/^(.+)navaa$/i);
    return rawPhoneticConvert(m[1]) + 'නවා';
  }
  // Verb question suffix: -nawada / -nawadha -> ...නවද
  if (/(.+)nawada$/i.test(word)) {
    const m = word.match(/^(.+)nawada$/i);
    return rawPhoneticConvert(m[1]) + 'නවද';
  }
  if (/(.+)nawadha$/i.test(word)) {
    const m = word.match(/^(.+)nawadha$/i);
    return rawPhoneticConvert(m[1]) + 'නවද';
  }
  // Question suffix: -da / -dha -> ...ද (e.g. puluwanda -> පුළුවන්ද)
  if (/(.+)da$/i.test(word) && !/(.+)ada$/i.test(word)) {
    const m = word.match(/^(.+)da$/i);
    return convertSinglishWord(m[1]) + 'ද';
  }
  if (/(.+)dha$/i.test(word) && !/(.+)adha$/i.test(word)) {
    const m = word.match(/^(.+)dha$/i);
    return convertSinglishWord(m[1]) + 'ද';
  }

  // Pre-process anusvara bindings for nk / ng (e.g. lankaa -> ලංකා, nangi -> නංගි)
  let w = word;
  w = w.replace(/([a-zA-Z])nk([a-zA-Z])/g, '$1ංක$2');
  w = w.replace(/([a-zA-Z])ng([a-zA-Z])/g, '$1ංග$2');

  return rawPhoneticConvert(w);
}

/**
 * Convert full Singlish text/paragraph to Sinhala Unicode
 */
function convertSinglish(text) {
  if (!text) return '';
  return text.split(/(\s+|[.,!?:;()[\]{}"'\\/])/).map(token => {
    if (/^\s+$/.test(token) || /^[.,!?:;()[\]{}"'\\/]+$/.test(token)) {
      return token;
    }
    // Only convert tokens with English/Latin letters
    if (!/[a-zA-Z]/.test(token)) {
      return token;
    }
    return convertSinglishWord(token);
  }).join('');
}

// Alias for backwards compatibility
function singlishToUnicode(text) {
  return convertSinglish(text);
}

