/**
 * Convert Tamil Unicode text to Legacy Bamini Font
 */
function unicodeToBamini(inputText) {
  if (!inputText) return '';
  let text = inputText;
  for (const [reg, rep] of TAMIL_UNI_TO_BAMINI) {
    text = text.replace(reg, rep);
  }
  return text;
}

/**
 * Convert Legacy Bamini Font text back to Tamil Unicode
 */
function baminiToUnicode(inputText) {
  if (!inputText) return '';
  let text = inputText;
  for (const [reg, rep] of BAMINI_TO_TAMIL_UNI) {
    text = text.replace(reg, rep);
  }
  return text;
}

/**
 * Auto-detect script of text: 'tamil' | 'sinhala' | 'other'
 */
function detectScript(text) {
  if (!text) return 'other';
  // Tamil unicode range: 0B80 - 0BFF
  const tamilMatches = text.match(/[\u0B80-\u0BFF]/g);
  // Sinhala unicode range: 0D80 - 0DFF
  const sinhalaMatches = text.match(/[\u0D80-\u0DFF]/g);

  const tamilCount = tamilMatches ? tamilMatches.length : 0;
  const sinhalaCount = sinhalaMatches ? sinhalaMatches.length : 0;

  if (tamilCount > sinhalaCount) return 'tamil';
  if (sinhalaCount > 0) return 'sinhala';
  return 'other';
}

